{% if doc.doctype == 'Production Briefing Form' and doc.custom_company == "Timbe Windows Private Limited" %}
<style>
/* =========================
   BASE TABLE STYLE
========================= */
table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10.5px;
}

th, td {
    border: 1px solid #000;
    padding: 3px 4px;
    vertical-align: top;
}

th {
    background: #333 !important;
    color: #fff !important;
    text-align: center;
    font-weight: bold;
    font-size: 11px;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

.center {
    text-align: center;
}

/* =========================
   HEADER
========================= */
.header-title {
    font-size: 26px;
    font-weight: bold;
    margin: 0;
}

/* =========================
   DESCRIPTION BLOCK
========================= */
td.desc-td {
    padding: 0 !important;
}

.item-name {
    font-weight: bold;
    font-size: 11px;
    padding: 4px 6px;
    border-bottom: 1px solid #000;
    background: #f9f9f9;
}

.desc-table td {
    padding: 2px 5px !important;
    line-height: 1.15 !important;
    font-size: 10px;
}

.desc-label {
    font-weight: 600;
}

.section-title {
    padding: 2px 6px !important;
    font-size: 10px;
    line-height: 1.1;
}

/* =========================
   DESCRIPTION TABLE
========================= */
.desc-table {
    width: 100%;
    border-collapse: collapse;
    font-size: 10px;
}

.desc-label {
    width: 40%;
    font-weight: bold;
}

.desc-value {
    width: 60%;
}

/* =========================
   SECTION TITLES (INLINE)
========================= */
.section-title {
    font-weight: bold;
    background: #efefef;
    padding: 3px 6px;
    border-bottom: 1px solid #000;
}

/* =========================
   IMAGE STYLE
========================= */
.img {
    max-width: 95%;
    max-height: 260px;
    display: block;
    margin: 4px auto;
}

/* =========================
   HEADER TABLE – NO BORDERS
========================= */
.header-table,
.header-table td {
    border: none !important;
}

/* =========================
   SIGNATURE & T&C SECTION
========================= */
.sig-tc-section {
    margin-top: 18px;
    page-break-inside: avoid;
}

.sig-tc-title {
    font-size: 13px;
    font-weight: bold;
    background: #333;
    color: #fff;
    padding: 5px 8px;
    -webkit-print-color-adjust: exact !important;
    print-color-adjust: exact !important;
}

.sig-box {
    border: 1px solid #000;
    min-height: 100px;
    padding: 6px;
    text-align: center;
    vertical-align: bottom;
}

.sig-img {
    max-height: 80px;
    max-width: 200px;
    display: block;
    margin: 0 auto 4px auto;
}

.sig-line {
    border-top: 1px solid #000;
    margin-top: 60px;
    font-size: 10px;
    padding-top: 3px;
}

.tc-box {
    border: 1px solid #000;
    border-top: none;
    padding: 8px 10px;
    font-size: 10px;
    line-height: 1.5;
}
</style>

<!-- =========================
     HEADER
========================= -->
<table class="header-table">
    <tr>
        <td style="width:40%;">
            <img src="/files/image_2023_08_24T15_11_53_538Z.png" style="height:55px;">
        </td>
        <td style="width:60%; text-align:right;">
            <div class="header-title">Production Briefing Form</div>
        </td>
    </tr>
</table>

<!-- =========================
     BASIC DETAILS
========================= -->
<table style="margin-top:5px;">
    <tr>
        <td><b>ID:</b> {{ doc.name }}</td>
        <td style="text-align:right;"><b>Quotation:</b> {{ doc.quotation }}</td>
    </tr>
    <tr>
        <td><b>Project:</b> {{ doc.project }}</td>
        <td style="text-align:right;"><b>Sales Person:</b> {{ doc.sales_person }}</td>
    </tr>
    <tr>
        <td><b>Delivery Date:</b> {{ frappe.utils.formatdate(doc.expected_delivery_date) }}</td>
        <td></td>
    </tr>
</table>

<!-- =========================
     ITEMS TABLE
========================= -->
<table style="margin-top:8px;">
    <tr>
        <th style="width:6%;">SL NO</th>
        <th style="width:54%;">DESCRIPTION</th>
        <th style="width:6%;">QTY</th>
        <th style="width:34%;">IMAGE</th>
    </tr>

    {% for row in doc.briefing_items %}
    <tr>
        <td class="center">{{ loop.index }}</td>

        <!-- ================= DESCRIPTION ================= -->
        <td class="desc-td">
            <div class="item-name">
                {{ row.item_code }} – {{ row.item_name }}
            </div>

            <table class="desc-table">
                <tr><td colspan="2" class="section-title">LOCATION DETAILS</td></tr>
                <tr><td class="desc-label">Floor</td><td class="desc-value">{{ row.custom_floor or "N/A" }}</td></tr>
                <tr><td class="desc-label">Place Type</td><td class="desc-value">{{ row.custom_type or "N/A" }}</td></tr>
                <tr><td class="desc-label">Place</td><td class="desc-value">{{ row.custom_place or "N/A" }}</td></tr>
                
                <tr>
                    <td class="desc-label">Window / Door No</td>
                    <td class="desc-value">
                        {% if row.custom_windowdoor_no %}
                            {% set item_group = frappe.db.get_value("Item", row.item_code, "item_group") %}
                            
                            {% if item_group == "Upvc Ventilators" %}
                                V{{ row.custom_windowdoor_no }}
                            {% elif item_group == "uPVC Windows" %}
                                W{{ row.custom_windowdoor_no }}
                            {% elif item_group == "Upvc Doors" %}
                                D{{ row.custom_windowdoor_no }}
                            {% else %}
                                C{{ row.custom_windowdoor_no }}
                            {% endif %}
                        {% else %}
                            N/A
                        {% endif %}
                    </td>
                </tr>

                <tr><td class="desc-label">Qty</td><td class="desc-value">{{ row.quantity }}</td></tr>

                <tr><td colspan="2" class="section-title">MEASUREMENT DETAILS</td></tr>

                {# ================= WIDTH ================= #}
                {% set widths = [] %}
                {% if row.custom_width_1 %}{% set _ = widths.append(row.custom_width_1 | int) %}{% endif %}
                {% if row.custom_width_2 %}{% set _ = widths.append(row.custom_width_2 | int) %}{% endif %}
                {% if row.custom_width_3 %}{% set _ = widths.append(row.custom_width_3 | int) %}{% endif %}
                
                <tr>
                    <td class="desc-label">Width</td>
                    <td class="desc-value">
                        {% if row.custom_width_1 %}W1-{{ row.custom_width_1 }}{% endif %}
                        {% if row.custom_width_2 %} / W2-{{ row.custom_width_2 }}{% endif %}
                        {% if row.custom_width_3 %} / W3-{{ row.custom_width_3 }}{% endif %}
                    </td>
                </tr>
                
                {% if widths | length > 1 %}
                <tr>
                    <td class="desc-label">Width Variance</td>
                    <td class="desc-value">{{ widths|max - widths|min }} mm</td>
                </tr>
                {% endif %}
                
                {# ================= HEIGHT ================= #}
                {% set heights = [] %}
                {% if row.custom_height_1 %}{% set _ = heights.append(row.custom_height_1 | int) %}{% endif %}
                {% if row.custom_height_2 %}{% set _ = heights.append(row.custom_height_2 | int) %}{% endif %}
                {% if row.custom_height_3 %}{% set _ = heights.append(row.custom_height_3 | int) %}{% endif %}
                
                <tr>
                    <td class="desc-label">Height</td>
                    <td class="desc-value">
                        {% if row.custom_height_1 %}H1-{{ row.custom_height_1 }}{% endif %}
                        {% if row.custom_height_2 %} / H2-{{ row.custom_height_2 }}{% endif %}
                        {% if row.custom_height_3 %} / H3-{{ row.custom_height_3 }}{% endif %}
                    </td>
                </tr>
                
                {% if heights | length > 1 %}
                <tr>
                    <td class="desc-label">Height Variance</td>
                    <td class="desc-value">{{ heights|max - heights|min }} mm</td>
                </tr>
                {% endif %}
                
                {# ===== SQUARE FEET ===== #}
                {% if widths and heights %}
                {% set min_width = widths|min %}
                {% set min_height = heights|min %}
                {% set sqft = (min_width * min_height) / 92903.04 %}
                
                <tr>
                    <td class="desc-label">Square Feet</td>
                    <td class="desc-value">
                        {{ "%.2f"|format(sqft) }} sq.ft
                        <span style="font-size:9px;">
                            ({{ min_width }} × {{ min_height }} mm)
                        </span>
                    </td>
                </tr>
                {% endif %}

                <tr><td class="desc-label">Unit Of Measure</td><td class="desc-value">{{ row.custom_unit_choice or "N/A" }}</td></tr>

                <tr><td colspan="2" class="section-title">GLASS DETAILS</td></tr>
                <tr><td class="desc-label">Glass Type</td><td class="desc-value">{{ row.custom_glass_type or "N/A" }}</td></tr>
                <tr><td class="desc-label">Glass Thickness</td><td class="desc-value">{{ row.custom_glass_thickness or "N/A" }}</td></tr>
                <tr><td class="desc-label">Glass Color</td><td class="desc-value">{{ row.custom_glass_color or "N/A" }}</td></tr>

                {% set item_name_lc = (row.item_name or "").lower() %}
                {% set is_sliding = "sliding" in item_name_lc %}
                {% set is_fixed_window = "fixed window" in item_name_lc %}
                {% set show_fan = ("ventilator" in item_name_lc) or ("louver" in item_name_lc) %}

                <tr><td colspan="2" class="section-title">HARDWARE</td></tr>
                
                {% if not is_sliding and not is_fixed_window %}
                <tr>
                    <td class="desc-label">Hinges</td>
                    <td class="desc-value">{{ row.custom_hinges or "N/A" }}</td>
                </tr>
                {% endif %}
                
                {% if not is_fixed_window %}
                <tr>
                    <td class="desc-label">Handle</td>
                    <td class="desc-value">{{ row.custom_handle or "N/A" }}</td>
                </tr>
                {% endif %}
                
                {% if not is_sliding and not is_fixed_window %}
                <tr>
                    <td class="desc-label">Opening</td>
                    <td class="desc-value">{{ row.custom_opening or "N/A" }}</td>
                </tr>
                {% endif %}

                <tr><td class="desc-label">uPVC Type</td><td class="desc-value">{{ row.custom_upvc_type or "N/A" }}</td></tr>
                <tr><td class="desc-label">Toughen</td><td class="desc-value">{{ row.custom_toughen or "N/A" }}</td></tr>
                
                {% if show_fan %}
                <tr>
                    <td class="desc-label">Fan</td>
                    <td class="desc-value">{{ row.custom_fan or "N/A" }}</td>
                </tr>
                {% endif %}

                <tr><td class="desc-label">Wall Thickness</td><td class="desc-value">{{ row.custom_wall_thickness or "N/A" }}</td></tr>
                
                <tr><td colspan="2" class="section-title">REMARKS</td></tr>
                <tr><td class="desc-label">Remarks</td><td class="desc-value">{{ row.additional_remarks or "N/A" }}</td></tr>
            </table>
        </td>

        <!-- ================= QTY ================= -->  
        <td class="center">{{ row.quantity }}</td>

        <!-- ================= IMAGE ================= -->
        <td class="center">
            {% set item_image = frappe.db.get_value("Item", row.item_code, "image") %}
            {% if item_image %}
            <img src="{{ frappe.utils.get_url() }}{{ item_image }}" class="img">
            {% endif %}

            {% set measurement_names = frappe.get_all(
                "Measurement",
                filters={"project": doc.project},
                pluck="name"
            ) %}

            {% for m in measurement_names %}
            {% set matched_measurement_item = frappe.get_all(
                "Installation Request Item",
                filters={
                    "parent": m,
                    "custom_item_name": row.item_name
                },
                fields=["custom_attach"],
                limit=1
            ) %}

            {% if matched_measurement_item and matched_measurement_item[0].custom_attach %}
            <img src="{{ frappe.utils.get_url() }}{{ matched_measurement_item[0].custom_attach }}"
                 class="img">
            {% endif %}
            {% endfor %}
        </td>
    </tr>

    {% if not loop.last %}
    <tr>
        <td colspan="4" style="border:none;">
            <div style="page-break-after:always;height:1px;"></div>
        </td>
    </tr>
    {% endif %}
    {% endfor %}
</table>

<!-- =========================
     CUSTOMER SIGNATURE & TERMS (Timbe)
     Fetched from linked Order Confirmation Form
========================= -->
{% if doc.quotation %}
{% set order_conf_list = frappe.get_all(
    "Order Confirmation Form",
    filters={"order_no": doc.quotation},
    fields=["name", "cus_sign", "sign_date", "terms"],
    limit=1
) %}

{% if order_conf_list %}
{% set ocf = order_conf_list[0] %}

<div class="sig-tc-section" style="margin-top:18px;">

    <!-- TERMS & CONDITIONS -->
    {% if ocf.terms %}
    {% set tc_doc = frappe.get_doc("Terms and Conditions", ocf.terms) %}
    <div class="sig-tc-title">Terms and Conditions</div>
    <div class="tc-box">
        {{ tc_doc.terms }}
    </div>
    {% endif %}

    <!-- SIGNATURE ROW -->
    <table style="margin-top:14px;">
        <tr>
            <!-- Customer Signature -->
            <td style="width:50%; padding:8px; text-align:center; vertical-align:bottom;">
                <div style="font-weight:bold; font-size:11px; margin-bottom:6px;">Customer Signature</div>
                {% if ocf.cus_sign %}
                {#
                    cus_sign is a Signature field — Frappe stores it as a base64 data URI
                    (e.g. "data:image/png;base64,iVBORw0K...").
                    Do NOT prepend get_url(); use the value directly as the src.
                #}
                <img src="{{ ocf.cus_sign }}"
                     style="max-height:80px; max-width:200px; display:block; margin:0 auto 6px auto;
                            -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
                {% else %}
                <div style="min-height:70px;"></div>
                {% endif %}
                <div style="border-top:1px solid #000; padding-top:4px; font-size:10px;">
                    {% if ocf.sign_date %}Sign Date: {{ frappe.utils.formatdate(ocf.sign_date) }}{% endif %}
                </div>
            </td>

            <!-- Authorised Signatory -->
            <td style="width:50%; padding:8px; text-align:center; vertical-align:bottom;">
                <div style="font-weight:bold; font-size:11px; margin-bottom:6px;">Authorised Signatory</div>
                <div style="min-height:70px;"></div>
                <div style="border-top:1px solid #000; padding-top:4px; font-size:10px;">
                    For Timbe Windows Private Limited
                </div>
            </td>
        </tr>
    </table>

</div>
{% endif %}
{% endif %}

{% endif %}


{% if doc.doctype == 'Production Briefing Form' and doc.custom_company == "Doortisan Creations Private Limited" %}
<style>
    table {
        width: 100%;
        border-collapse: collapse;
        font-size: 11px;
    }
    th, td {
        border: 1px solid #000;
    }
    th {
        background: #333333 !important;
        color: #ffffff !important;
        text-align: center;
        font-weight: bold;
        -webkit-print-color-adjust: exact !important;
        print-color-adjust: exact !important;
    }
    .center {
        text-align: center;
    }
    td.desc-td {
        padding: 0 !important;
        margin: 0 !important;
    }
    .item-name {
        font-weight: bold;
        font-size: 11px;
        padding: 5px 6px 3px 6px;
        margin: 0;
        border-bottom: 1px solid #000;
        line-height: 1.3;
    }
    .desc-table {
        width: 100%;
        border-collapse: collapse;
        font-size: 10.5px;
        margin: 0;
        padding: 0;
        border: none;
    }
    .desc-table tr {
        margin: 0;
        padding: 0;
    }
    .desc-table td {
        border: none;
        border-bottom: 0.8px solid #000;
        padding: 3px 5px !important;
        line-height: 1.25;
        margin: 0;
        vertical-align: top;
    }
    .desc-label {
        width: 38%;
        text-align: left;
        border-right: 1px solid #000 !important;
        border-left: none !important;
        padding: 3px 5px 3px 6px !important;
        vertical-align: top;
    }
    .desc-value {
        width: 62%;
        text-align: left;
        border-left: none !important;
        padding: 3px 6px !important;
        white-space: normal;
        word-wrap: break-word;
        line-height: 1.25;
    }
    .img {
        width: 100%;
        max-width: 100%;
        height: auto;
        max-height: 220px;
        object-fit: contain;
        display: block;
        margin: 4px auto;
    }
    .img-container {
        width: 100%;
        text-align: center;
    }
    .img-label {
        font-weight: bold;
        font-size: 10px;
        margin-bottom: 4px;
        text-align: center;
    }

    @media print {
        .img {
            max-height: 220px;
            width: auto;
            max-width: 100%;
            display: block;
            margin: 4px auto;
            -webkit-print-color-adjust: exact !important;
            print-color-adjust: exact !important;
        }
        .img-container {
            width: 100%;
            text-align: center;
        }
        table { page-break-inside: auto; }
        tr { page-break-inside: avoid; }
        .sig-section { page-break-inside: avoid; }
    }
</style>

<table style="width: 100%; border-collapse: collapse;">
    <tr>
        <td style="width: 35%; border:1px solid #000; border-right: none;">
            <img src="/files/image_2023_08_24T15_16_35_199Z.png" style="height: 50px;">
        </td>
        <td style="width: 55%; text-align: right; border:1px solid #000; border-left: none;">
            <h2 style="margin: 0; font-weight: bold; font-size: 25px;">
                Production Briefing Form
            </h2>
        </td>
    </tr>
</table>

<div class="section-title"> </div>

<table style="width: 100%; font-size: 11px; table-layout: fixed;">
    <tr>
        <td style="width:50%;">
            <strong>ID:</strong> {{ doc.name }}
        </td>
        <td style="width:50%;">
            <strong>Quotation:</strong> {{ doc.quotation }}
        </td>
    </tr>
    <tr>
        <td>
            <strong>Project:</strong> {{ doc.project }}
        </td>
        <td>
            <strong>Sales Person:</strong> {{ doc.sales_person }}
        </td>
    </tr>
    <tr>
        <td>
            <strong>Delivery Date:</strong>
            {{ frappe.utils.formatdate(doc.expected_delivery_date) }}
        </td>
        <td>
            <strong>Customer:</strong>
            {% if doc.quotation %}
                {% set quotation = frappe.get_doc("Quotation", doc.quotation) %}
                {{ quotation.customer_name }}
            {% else %}
                Unknown
            {% endif %}
        </td>
    </tr>
    <tr>
        <td>
            <strong>Sales Confirmation Date:</strong>
            {{ frappe.utils.formatdate(doc.sales_confirmation_date) }}
        </td>
        <td>
            <strong>Production Date:</strong>
            {{ frappe.utils.formatdate(doc.approved_date) }}
        </td>
    </tr>
</table>

<table>
    <tr>
        <th style="width:6%;">SL NO</th>
        <th style="width:50%;">DESCRIPTION</th>
        <th style="width:10%;">QUANTITY</th>
        <th style="width:34%;">IMAGE</th>
    </tr>

    {% for row in doc.briefing_items or [] %}
    <tr>
        <td class="center">{{ loop.index }}</td>
        <td class="desc-td">
            <div class="item-name">{{ row.item_name }}</div>
            <table class="desc-table">
                <tr><td class="desc-label">Code:</td><td class="desc-value">{{ row.item_code or "N/A" }}</td></tr>
                <tr><td class="desc-label">Application:</td><td class="desc-value">{{ row.application or "N/A" }}</td></tr>
                <tr><td class="desc-label">Floor:</td><td class="desc-value">{{ row.custom_floor or "N/A" }}</td></tr>
                <tr><td class="desc-label">Place of Fixing:</td><td class="desc-value">{{ row.application or "N/A" }}</td></tr>
                <tr><td class="desc-label">Door Type:</td><td class="desc-value">{{ row.item_name or "N/A" }}</td></tr>
                <tr><td class="desc-label">Product Type:</td><td class="desc-value">{{ row.product or "N/A" }}</td></tr>
                <tr><td class="desc-label">Shutter Type:</td><td class="desc-value">{{ row.shutter_type or "N/A" }}</td></tr>
                <tr><td class="desc-label">Open Type:</td><td class="desc-value">{{ row.custom_open_type or "N/A" }}</td></tr>
                <tr><td class="desc-label">Product Grade:</td><td class="desc-value">{{ row.flush_grade or "N/A" }}</td></tr>
                <tr><td class="desc-label">Product Size:</td><td class="desc-value">{{ row.product_size or "N/A" }}</td></tr>

                {% if row.laminate == 1 or row.custom_laminates %}
                {% set front_side = row.custom_laminates.split("Back Side:")[0].strip() if row.custom_laminates else "" %}
                {% set back_side = row.custom_laminates.split("Back Side:")[1].strip() if row.custom_laminates and "Back Side:" in row.custom_laminates else "" %}
                <tr>
                    <td colspan="2" style="font-weight:900; background-color:#333333; color:#ffffff; padding:4px 3px !important; text-align:center; font-size:10px; letter-spacing:0.5px; border:1px solid #333; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
                        LAMINATED DOOR DESIGN
                    </td>
                </tr>
                {% if row.laminate_thickness %}
                <tr><td class="desc-label">Laminate Thickness:</td><td class="desc-value">{{ row.laminate_thickness }}</td></tr>
                {% endif %}
                {% if front_side %}
                <tr><td class="desc-label">Front Side Code:</td><td class="desc-value">{{ front_side }}</td></tr>
                {% endif %}
                {% if back_side %}
                <tr><td class="desc-label">Back Side Code:</td><td class="desc-value">{{ back_side }}</td></tr>
                {% endif %}
                {% endif %}

                {% if row.category == "Wood" %}
                <tr>
                    <td colspan="2" style="font-weight:900; background-color:#333333; color:#ffffff; padding:4px 3px !important; text-align:center; font-size:10px; letter-spacing:0.5px; border:1px solid #333; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
                        WOOD DETAILS
                    </td>
                </tr>
                <tr><td class="desc-label">Wood Grade:</td><td class="desc-value">{{ row.wood_grade or "N/A" }}</td></tr>
                <tr><td class="desc-label">Wood Type:</td><td class="desc-value">{{ row.wood_type or "N/A" }}</td></tr>
                {% endif %}

                {% if row.grill == 1 %}
                <tr>
                    <td colspan="2" style="font-weight:900; background-color:#333333; color:#ffffff; padding:4px 3px !important; text-align:center; font-size:10px; letter-spacing:0.5px; border:1px solid #333; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
                        GRILL DETAILS
                    </td>
                </tr>
                <tr><td class="desc-label">Grill Model:</td><td class="desc-value">{{ row.grill_details or "N/A" }}</td></tr>
                {% endif %}

                {% if row.threshold == 1 %}
                <tr>
