<!-- =========================
     CUSTOMER SIGNATURE & TERMS (Doortisan)
     Fetched from linked Order Confirmation Form
========================= -->
{% if doc.quotation %}
{% set order_conf_list = frappe.get_all(
    "Order Confirmation Form",
    filters={"order_no": doc.quotation},
    fields=["name", "cus_sign", "sign_date", "terms"],
    limit=1
) %}

{% if order_conf_list %}
{% set ocf = order_conf_list[0] %}

<div style="margin-top:18px; page-break-inside:avoid;">

    <!-- TERMS & CONDITIONS -->
    {% if ocf.terms %}
    {% set tc_doc = frappe.get_doc("Terms and Conditions", ocf.terms) %}
    <div style="font-size:13px; font-weight:bold; background:#333; color:#fff; padding:5px 8px;
                -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
        Terms and Conditions
    </div>
    <div style="border:1px solid #000; border-top:none; padding:8px 10px; font-size:10px; line-height:1.5;">
        {{ tc_doc.terms }}
    </div>
    {% endif %}

    <!-- PRODUCT DESIGN IMAGES (summary at bottom) -->
    {% set has_designs = [] %}
    {% for row in doc.briefing_items or [] %}
        {% if row.product_design or row.custom_edited_image %}
            {% set _ = has_designs.append(1) %}
        {% endif %}
    {% endfor %}

    {% if has_designs %}
    <div style="margin-top:14px; page-break-inside:avoid;">
        <div style="font-size:13px; font-weight:bold; background:#333; color:#fff; padding:5px 8px;
                    -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
            Product Design Images
        </div>
        <table style="margin-top:0; border-top:none; table-layout:fixed; width:100%;">
            <tr>
                {% for row in doc.briefing_items or [] %}
                {% if row.product_design or row.custom_edited_image %}
                <td style="text-align:center; vertical-align:top; padding:6px; border:1px solid #ccc; width:25%;">
                    <div style="font-size:9px; font-weight:bold; margin-bottom:4px; color:#333;">
                        {{ loop.index }}. {{ row.item_name }}
                    </div>
                    {% if row.product_design %}
                    <img src="{{ frappe.utils.get_url() }}{{ row.product_design }}"
                         style="max-width:100%; max-height:160px; width:auto; display:block; margin:0 auto 4px auto;
                                object-fit:contain; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
                    {% endif %}
                    {% if row.custom_edited_image %}
                    <img src="{{ frappe.utils.get_url() }}{{ row.custom_edited_image }}"
                         style="max-width:100%; max-height:160px; width:auto; display:block; margin:0 auto;
                                object-fit:contain; -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
                    {% endif %}
                </td>
                {% endif %}
                {% endfor %}
            </tr>
        </table>
    </div>
    {% endif %}

    <!-- SIGNATURE ROW -->
    <table style="margin-top:14px;">
        <tr>
            <td style="padding:8px 10px;">
                <div style="font-size:10px; font-style:italic; color:#333; margin-bottom:10px;">
                    I hereby confirm that I have read, understood, and agree to the above terms and conditions associated with my order.
                </div>
                <div style="font-weight:bold; font-size:11px; margin-bottom:6px;">Customer Signature</div>
                {% if ocf.cus_sign %}
                {#
                    cus_sign is a Signature field — Frappe stores it as a base64 data URI
                    (e.g. "data:image/png;base64,iVBORw0K...").
                    Do NOT prepend get_url(); use the value directly as the src.
                #}
                <img src="{{ ocf.cus_sign }}"
                     style="max-height:80px; max-width:200px; display:block; margin:0 0 6px 0;
                            -webkit-print-color-adjust:exact !important; print-color-adjust:exact !important;">
                {% else %}
                <div style="min-height:70px;"></div>
                {% endif %}
                <div style="border-top:1px solid #000; padding-top:4px; font-size:10px;">
                    {% if ocf.sign_date %}Sign Date: {{ frappe.utils.formatdate(ocf.sign_date) }}{% endif %}
                </div>
            </td>
        </tr>
    </table>

</div>
{% endif %}
{% endif %}

{% endif %}
